import assert from 'node:assert/strict';
import test from 'node:test';
import {execFileSync} from 'node:child_process';
import {cpSync, mkdtempSync, readFileSync, rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {REPOSITORY, REVISION_SITES, VERSION_SITES, pin, registered} from './lexlean-pin.mjs';

// Records of past pins, vendored or generated bytes, and the register itself,
// which scripts/reconcile-lexlean.mjs rewrites.
const HISTORY = [
  /^CHANGELOG\.md$/, /^RELEASE_NOTES\.md$/, /^VERIFICATION\.md$/, /\/VERIFICATION\.md$/, /^docs\/release\//,
  /^vendor\//, /^tests\/golden\//, /^model\/dependencies\.toml$/, /\.inspect\.(json|txt)$/,
];
// Tracked files, outside the history, that contain any of the needles.
const carriers = needles => [...new Set(needles.flatMap(needle => {
  try {
    return execFileSync('git', ['grep', '-l', '-F', '-I', '-e', needle], {cwd: REPOSITORY, encoding: 'utf8', maxBuffer: 1 << 26})
      .split('\n').filter(Boolean);
  } catch (error) { if (error.status === 1) return []; throw error; }
}))].filter(path => !HISTORY.some(pattern => pattern.test(path)));
const current = () => registered(readFileSync(join(REPOSITORY, 'model/dependencies.toml'), 'utf8'));

test('every tracked copy of the LexLean revision is a declared site', () => {
  const {revision} = current();
  const hits = carriers([revision]);
  assert.deepEqual(hits.filter(path => !REVISION_SITES.includes(path)), [], 'add these files to REVISION_SITES');
  assert.deepEqual(REVISION_SITES.filter(path => !hits.includes(path)), [], 'stale REVISION_SITES entries');
});

test('every tracked lexlean-<version> or crate pin is a declared site', () => {
  const {version} = current();
  const needles = [`lexlean-${version}`, `lexlean ${version}`, `"lexlean"], "${version}"`];
  const hits = carriers(needles);
  assert.deepEqual(hits.filter(path => !(path in VERSION_SITES)), [], 'add these files to VERSION_SITES');
});

test('a bump rewrites every site, and a repeat without reconcile refuses', t => {
  const root = mkdtempSync(join(tmpdir(), 'lexlean-pin-'));
  t.after(() => rmSync(root, {recursive: true, force: true}));
  const files = new Set(['model/dependencies.toml', ...REVISION_SITES, ...Object.keys(VERSION_SITES)]);
  for (const path of files) cpSync(join(REPOSITORY, path), join(root, path), {recursive: true});
  const from = current();
  const to = {revision: 'f'.repeat(40), version: '9.8.7'};
  const result = pin(root, to);
  assert.deepEqual(result.from, from);
  assert.deepEqual(result.changed.sort(), [...new Set([...REVISION_SITES, ...Object.keys(VERSION_SITES)])].sort());
  for (const path of REVISION_SITES) {
    const text = readFileSync(join(root, path), 'utf8');
    assert.ok(!text.includes(from.revision) && text.includes(to.revision), path);
  }
  assert.match(readFileSync(join(root, 'scripts/reconcile-lexlean.mjs'), 'utf8'), /LEXLEAN_VERSION='9\.8\.7'/);
  assert.match(readFileSync(join(root, 'scripts/release-phases.test.mjs'), 'utf8'), /wait_for_crate lexlean 9\\\.8\\\.7/);
  // The register is reconcile's to rewrite, so a second run sees the old pin
  // and its sites have moved: it must refuse rather than half-apply.
  assert.throws(() => pin(root, to), /no longer carries/);
});

test('a bump refuses an abbreviated revision or a range version', () => {
  assert.throws(() => pin(REPOSITORY, {revision: 'e0b74b81', version: '0.5.0'}), /full commit hash/);
  assert.throws(() => pin(REPOSITORY, {revision: 'a'.repeat(40), version: '^0.5'}), /exact/);
});

test('native records import only with exact bytes for the named commit', async t => {
  const {createHash} = await import('node:crypto');
  const {mkdirSync, writeFileSync} = await import('node:fs');
  const {RECORDS, importRecords} = await import('./lexlean-sync-native.mjs');
  const root = mkdtempSync(join(tmpdir(), 'lexlean-native-'));
  t.after(() => rmSync(root, {recursive: true, force: true}));
  const commit = 'a'.repeat(40);
  const artifacts = join(root, 'artifacts'), repo = join(root, 'repo');
  for (const arch of ['amd64', 'arm64']) {
    const records = RECORDS.map(path => {
      const bytes = Buffer.from(`${arch}:${path}\n`);
      mkdirSync(join(artifacts, arch, 'records', path, '..'), {recursive: true});
      writeFileSync(join(artifacts, arch, 'records', path), bytes);
      mkdirSync(join(repo, `tests/golden/native/linux-${arch}-ubuntu-24.04/verified`), {recursive: true});
      return {path, byte_length: bytes.length, sha256: createHash('sha256').update(bytes).digest('hex')};
    });
    writeFileSync(join(artifacts, arch, 'review.json'), JSON.stringify({schema: 'prismpm/native-golden-review/1',
      status: 'review-required', source_revision: commit, platform: `linux-${arch}-ubuntu-24.04`, records}));
  }
  assert.throws(() => importRecords(repo, 'b'.repeat(40), artifacts), /another commit/);
  writeFileSync(join(artifacts, 'arm64/records/golden-manifest.json'), 'tampered');
  assert.throws(() => importRecords(repo, commit, artifacts), /length|digest/);
  assert.throws(() => readFileSync(join(repo, 'tests/golden/native/linux-amd64-ubuntu-24.04/golden-manifest.json')), /ENOENT/,
    'nothing is written unless both architectures verify');
  writeFileSync(join(artifacts, 'arm64/records/golden-manifest.json'), 'arm64:golden-manifest.json\n');
  assert.equal(importRecords(repo, commit, artifacts).length, 6);
  assert.equal(readFileSync(join(repo, 'tests/golden/native/linux-arm64-ubuntu-24.04/verified/manifest.json'), 'utf8'),
    'arm64:verified/manifest.json\n');
});
